public class Main {
    public static void main(String[] args) {
        StringBuilder digits = new StringBuilder();
        for (int i = 1; i <= 5; i++) {
            digits.append(i);
        }

        StringBuilder row = new StringBuilder();
        for (int i = 0; i < 8; i++) {
            row.append('#');
        }

        System.out.println(digits + " has length " + digits.length());
        System.out.println(row.toString() + " has length " + row.length());

        StringBuilder other = new StringBuilder();
        other.append(12).append("345");
        System.out.println("equals: " + digits.equals(other));
        System.out.println("same text: " + digits.toString().equals(other.toString()));
    }
}

