public class Main {
    public static void main(String[] args) {
        StringBuilder letters = new StringBuilder();
        StringBuilder evens = new StringBuilder();

        for (int i = 0; i < 8; i++) {
            letters.append((char) ('A' + i));
        }
        for (int n = 2; n <= 8; n += 2) {
            evens.append(n);
        }

        System.out.println(letters + " has length " + letters.length());
        System.out.println(evens + " has length " + evens.length());

        StringBuilder copy = new StringBuilder();
        copy.append("ABCD").append("EFGH");
        System.out.println("same text: " + letters.toString().equals(copy.toString()));
    }
}

