public class Main {
    public static void main(String[] args) {
        String[] names = {"Ana", "Bruno", "Li", "Carla", "Tom", "Diego"};

        StringBuilder sb = new StringBuilder();
        for (String name : names) {
            if (name.length() > 3) {
                if (sb.length() > 0) {
                    sb.append(" | ");
                }
                sb.append(name);
            }
        }

        System.out.println("Long names: " + sb);
    }
}
